"use client";

import { useMemo } from "react";
import {
  readApiResource,
  useApiResource,
  type ApiResourceAdapter,
} from "./use-api-resource";

export type TransactionHistoryCluster = "mainnet-beta" | "devnet" | "testnet";
export type TransactionHistoryItem = {
  signature: string;
  slot: number;
  blockTime: string | null;
  memo: string | null;
  status: "processed" | "confirmed" | "finalized" | "failed";
  error: unknown | null;
};
export type TransactionHistoryData = {
  address: string;
  cluster: TransactionHistoryCluster;
  items: TransactionHistoryItem[];
  nextCursor: string | null;
};
export type TransactionHistoryInput = {
  address: string;
  cluster: TransactionHistoryCluster;
  limit: number;
  before?: string;
};
export type TransactionHistoryAdapter = ApiResourceAdapter<
  TransactionHistoryInput,
  TransactionHistoryData
>;

export function createTransactionHistoryAdapter(
  endpoint = "/api/transaction-history",
): TransactionHistoryAdapter {
  return async ({ address, cluster, limit, before }, { signal }) => {
    const url = new URL(endpoint, window.location.origin);
    url.searchParams.set("address", address);
    url.searchParams.set("cluster", cluster);
    url.searchParams.set("limit", String(limit));
    if (before) url.searchParams.set("before", before);
    return readApiResource<TransactionHistoryData>(await fetch(url, { signal }));
  };
}

export function useTransactionHistory(
  address: string | null | undefined,
  options: {
    adapter?: TransactionHistoryAdapter;
    endpoint?: string;
    enabled?: boolean;
    cluster?: TransactionHistoryCluster;
    limit?: number;
    before?: string;
  } = {},
) {
  const normalizedAddress = address?.trim() ?? "";
  const cluster = options.cluster ?? "mainnet-beta";
  const limit = Math.min(50, Math.max(1, options.limit ?? 10));
  const defaultAdapter = useMemo(
    () => createTransactionHistoryAdapter(options.endpoint),
    [options.endpoint],
  );

  return useApiResource({
    adapter: options.adapter ?? defaultAdapter,
    enabled: (options.enabled ?? true) && normalizedAddress.length > 0,
    input: {
      address: normalizedAddress,
      cluster,
      limit,
      before: options.before,
    },
    requestKey: `${cluster}:${normalizedAddress}:${limit}:${options.before ?? ""}`,
  });
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export type ApiResourceStatus = "idle" | "loading" | "success" | "error";

export type ApiResourceError = {
  code: string;
  message: string;
  retryable: boolean;
  status?: number;
};

export type ApiResourceAdapter<Input, Data> = (
  input: Input,
  context: { signal: AbortSignal },
) => Promise<Data>;

export type ApiResourceState<Data> = {
  status: ApiResourceStatus;
  data: Data | null;
  error: ApiResourceError | null;
  updatedAt: string | null;
};

type ApiEnvelope<Data> = {
  data?: Data;
  error?: Partial<ApiResourceError> & { message?: string };
};

export class ApiResourceRequestError extends Error {
  code: string;
  retryable: boolean;
  status?: number;

  constructor(error: ApiResourceError) {
    super(error.message);
    this.name = "ApiResourceRequestError";
    this.code = error.code;
    this.retryable = error.retryable;
    this.status = error.status;
  }
}

export async function readApiResource<Data>(response: Response) {
  let body: ApiEnvelope<Data>;

  try {
    body = (await response.json()) as ApiEnvelope<Data>;
  } catch {
    throw new ApiResourceRequestError({
      code: "INVALID_RESPONSE",
      message: "The provider returned an unreadable response.",
      retryable: true,
      status: response.status,
    });
  }

  if (!response.ok || body.error || body.data === undefined) {
    throw new ApiResourceRequestError({
      code: body.error?.code || "REQUEST_FAILED",
      message: body.error?.message || "The provider request failed.",
      retryable: body.error?.retryable ?? response.status >= 500,
      status: response.status,
    });
  }

  return body.data;
}

function normalizeError(cause: unknown): ApiResourceError {
  if (cause instanceof ApiResourceRequestError) {
    return {
      code: cause.code,
      message: cause.message,
      retryable: cause.retryable,
      status: cause.status,
    };
  }

  return {
    code: "UNKNOWN_ERROR",
    message: cause instanceof Error ? cause.message : "The request failed.",
    retryable: true,
  };
}

export function useApiResource<Input, Data>({
  adapter,
  enabled,
  input,
  requestKey,
}: {
  adapter: ApiResourceAdapter<Input, Data>;
  enabled: boolean;
  input: Input;
  requestKey: string;
}) {
  const inputRef = useRef(input);
  const requestIdRef = useRef(0);
  const [refreshKey, setRefreshKey] = useState(0);
  const [state, setState] = useState<ApiResourceState<Data>>({
    status: "idle",
    data: null,
    error: null,
    updatedAt: null,
  });

  useEffect(() => {
    inputRef.current = input;
  }, [input]);

  useEffect(() => {
    if (!enabled) return;

    const requestId = ++requestIdRef.current;
    const controller = new AbortController();
    const loadingTimer = window.setTimeout(() => {
      setState((current) => ({
        ...current,
        status: "loading",
        error: null,
      }));
    }, 0);

    void adapter(inputRef.current, { signal: controller.signal })
      .then((data) => {
        window.clearTimeout(loadingTimer);
        if (controller.signal.aborted || requestId !== requestIdRef.current) {
          return;
        }
        setState({
          status: "success",
          data,
          error: null,
          updatedAt: new Date().toISOString(),
        });
      })
      .catch((cause: unknown) => {
        window.clearTimeout(loadingTimer);
        if (controller.signal.aborted || requestId !== requestIdRef.current) {
          return;
        }
        setState((current) => ({
          ...current,
          status: "error",
          error: normalizeError(cause),
        }));
      });

    return () => {
      window.clearTimeout(loadingTimer);
      controller.abort();
    };
  }, [adapter, enabled, refreshKey, requestKey]);

  const refetch = useCallback(() => setRefreshKey((value) => value + 1), []);
  const visibleState: ApiResourceState<Data> = enabled
    ? state
    : { status: "idle", data: null, error: null, updatedAt: null };

  return {
    ...visibleState,
    isIdle: visibleState.status === "idle",
    isLoading: visibleState.status === "loading",
    isSuccess: visibleState.status === "success",
    isError: visibleState.status === "error",
    refetch,
  };
}

import {
  address as parseAddress,
  createSolanaRpc,
  signature as parseSignature,
  type Address,
} from "@solana/kit";
import { NextResponse } from "next/server";

export const runtime = "nodejs";
type ClusterValue = "mainnet-beta" | "devnet" | "testnet";
const CLUSTERS = new Set<ClusterValue>(["mainnet-beta", "devnet", "testnet"]);

function jsonError(code: string, message: string, status: number, retryable = false) {
  return NextResponse.json({ error: { code, message, retryable } }, { status });
}

function rpcUrl(cluster: ClusterValue) {
  if (cluster === "mainnet-beta") {
    return process.env.MAINNET_RPC || "https://api.mainnet-beta.solana.com";
  }
  if (cluster === "devnet") {
    return process.env.DEVNET_RPC || "https://api.devnet.solana.com";
  }
  return "https://api.testnet.solana.com";
}

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const address = searchParams.get("address")?.trim() ?? "";
  const clusterParam = searchParams.get("cluster") || "mainnet-beta";
  const limit = Math.min(50, Math.max(1, Number(searchParams.get("limit")) || 10));
  const before = searchParams.get("before")?.trim() || undefined;
  if (!CLUSTERS.has(clusterParam as ClusterValue)) return jsonError("INVALID_CLUSTER", "Unsupported Solana cluster.", 400);

  let publicKey: Address;
  try {
    publicKey = parseAddress(address);
  } catch {
    return jsonError("INVALID_ADDRESS", "A valid Solana account address is required.", 400);
  }
  let beforeSignature;
  try {
    beforeSignature = before ? parseSignature(before) : undefined;
  } catch {
    return jsonError("INVALID_CURSOR", "The transaction cursor is invalid.", 400);
  }
  const cluster = clusterParam as ClusterValue;

  try {
    const signatures = await createSolanaRpc(rpcUrl(cluster))
      .getSignaturesForAddress(publicKey, {
        before: beforeSignature,
        commitment: "confirmed",
        limit,
      })
      .send();
    const items = signatures.map((item) => ({
      signature: item.signature,
      slot: Number(item.slot),
      blockTime: item.blockTime
        ? new Date(Number(item.blockTime) * 1_000).toISOString()
        : null,
      memo: item.memo,
      status: item.err ? "failed" : item.confirmationStatus || "processed",
      error: item.err,
    }));
    return NextResponse.json({
      data: {
        address,
        cluster,
        items,
        nextCursor: items.at(-1)?.signature ?? null,
      },
    });
  } catch {
    return jsonError("RPC_UNAVAILABLE", `Could not reach the ${cluster} RPC.`, 503, true);
  }
}
